$('restoreInput').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{const obj=JSON.parse(await f.text());if(!Array.isArray(obj.safaris)||!Array.isArray(obj.expenses)||obj.safaris.some(r=>!r.id||!r.reg||!r.customer||!r.start||!r.end||!(Number(r.days)>0)||Number(r.rate)<0)||obj.expenses.some(x=>!x.id||!x.safariId||!x.date||!x.type||!(Number(x.amount)>0)||!(Number(x.fx)>0)||!['TZS','USD'].includes(x.currency)))throw Error('Invalid backup format');if(!await window.authorizeDeletion('Replace ALL existing data with this backup?'))return;if(obj.payments!==undefined&&(!Array.isArray(obj.payments)||obj.payments.some(p=>!p.id||!p.safariId||!p.date||!['Advance','Additional','Final'].includes(p.type)||!(Number(p.amount)>0)||!(Number(p.fx)>0)||!['TZS','USD'].includes(p.currency))))throw Error('Invalid payment records');if(obj.vehicleExpenses!==undefined&&(!Array.isArray(obj.vehicleExpenses)||obj.vehicleExpenses.some(x=>!x.id||!x.reg||!x.date||!x.type||!(Number(x.amount)>0)||!(Number(x.fx)>0)||!['TZS','USD'].includes(x.currency))))throw Error('Invalid vehicle maintenance records');const previous=db;db={safaris:obj.safaris,expenses:obj.expenses,payments:obj.payments||[],vehicleExpenses:obj.vehicleExpenses||[],vehicleTypes:obj.vehicleTypes||{},ownerRepayments:Array.isArray(obj.ownerRepayments)?obj.ownerRepayments:[],invoiceSequence:Math.max(db.invoiceSequence||0,obj.invoiceSequence||0),management:obj.management||{}};if(!persist()){db=previous;return}notify('Backup restored successfully.');}catch(err){notify('Could not restore: '+err.message)}finally{e.target.value=''}});
