// Dashboard, customer invoices and receipts, and unpaid balance alerts.
$('dashboardMonth').value=today.slice(0,7);
$('dashboardMonth').addEventListener('change',renderNewFeatures);
$('alertFilter').addEventListener('change',renderNewFeatures);
$('documentSafari').addEventListener('change',renderNewFeatures);
function renderNewFeatures(){
 const m=$('dashboardMonth').value;
 const bookings=db.safaris.filter(r=>r.start?.slice(0,7)===m);
 const payments=db.payments.filter(x=>x.date?.slice(0,7)===m);
 const exp=db.expenses.filter(x=>x.date?.slice(0,7)===m);
 const maintenance=db.vehicleExpenses.filter(x=>x.date?.slice(0,7)===m);
 const inc=bookings.reduce((s,r)=>s+recIncome(r),0), received=payments.reduce((s,x)=>s+payUSD(x),0), expense=exp.reduce((s,x)=>s+expUSD(x),0), maint=maintenance.reduce((s,x)=>s+expUSD(x),0);
 const outstanding=bookings.reduce((s,r)=>s+Math.max(0,recIncome(r)-recReceived(r)),0);
 for(const [id,val] of Object.entries({dashIncome:money(inc),dashReceived:money(received),dashOutstanding:money(outstanding),dashExpenses:money(expense),dashMaintenance:money(maint),dashProfit:money(inc-expense-maint),dashCash:money(received-[...exp,...maintenance].filter(e=>e.source!=='personal'&&e.source!=='capital').reduce((s,e)=>s+expUSD(e),0)),dashCount:bookings.filter(r=>safariStatus(r)==='ongoing').length+' / '+bookings.filter(r=>safariStatus(r)==='completed').length}))$(id).textContent=val;
 window.renderFinanceOverview?.();
 if(!$('calendarMonth').value)$('calendarMonth').value=m;
 renderDashboardCalendar($('calendarMonth').value);
 const unpaid=db.safaris.filter(r=>recIncome(r)-recReceived(r)>0.005);
 $('dashAlertsSummary').innerHTML=`<div class="entry"><strong>${unpaid.length} outstanding booking(s) · ${money(unpaid.reduce((sum,r)=>sum+Math.max(0,recIncome(r)-recReceived(r)),0))}</strong><small>${unpaid.filter(r=>paymentStatus(r)==='Overdue').length} overdue. Includes bookings with no payment recorded.</small></div>`;
 $('dashDocumentsSummary').innerHTML=`<div class="entry"><strong>${db.safaris.length} safari invoice(s) available · ${db.payments.length} recorded payment receipt(s)</strong><small>Choose Invoices & Receipts to select a customer and print a document.</small></div>`;
 $('dashBookings').innerHTML=bookings.map(r=>`<div class="entry"><strong>${escapeHtml(r.customer)} · ${escapeHtml(r.reg)}</strong><small>${escapeHtml(r.start)} to ${escapeHtml(r.end)} · Expected ${money(recIncome(r))} · Received ${money(recReceived(r))} · Outstanding ${money(Math.max(0,recIncome(r)-recReceived(r)))}</small></div>`).join('')||'<p class="hint">No safaris start in this month.</p>';
 const selected=$('documentSafari').value;
 $('documentSafari').innerHTML='<option value="">Select safari</option>'+db.safaris.map(r=>`<option value="${escapeHtml(r.id)}">${escapeHtml(r.customer)} · ${escapeHtml(r.reg)} · ${escapeHtml(r.start)}</option>`).join('');
 if(db.safaris.some(r=>r.id===selected))$('documentSafari').value=selected;
 const r=db.safaris.find(x=>x.id===$('documentSafari').value);
 $('documentSummary').innerHTML=r?`<div class="entry"><strong>${escapeHtml(r.customer)}</strong><small>Booking: ${escapeHtml(r.start)} to ${escapeHtml(r.end)} · Expected ${money(recIncome(r))} · Received ${money(recReceived(r))} · Balance ${money(Math.max(0,recIncome(r)-recReceived(r)))} · ${escapeHtml(paymentStatus(r))}</small></div>`:'<p class="hint">Select a booking to generate an invoice or view payment receipts.</p>';
 $('receiptList').innerHTML=r?paymentsFor(r).map(p=>`<div class="entry"><div class="line"><strong>${escapeHtml(r.customer)} · ${escapeHtml(p.date)} · ${escapeHtml(p.type)} · ${escapeHtml(p.currency)} ${Number(p.amount).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</strong><button type="button" data-print-receipt="${escapeHtml(p.id)}">View / Print Receipt</button></div></div>`).join('')||'<p class="hint">No recorded payments. Receipts are available only after a payment is saved.</p>':'';
 const owing=db.safaris.filter(r=>recIncome(r)-recReceived(r)>0.005);
 $('alertCount').textContent=String(owing.length);
 $('alertTotal').textContent=money(owing.reduce((s,r)=>s+Math.max(0,recIncome(r)-recReceived(r)),0));
 $('alertOverdue').textContent=String(owing.filter(r=>paymentStatus(r)==='Overdue').length);
 const f=$('alertFilter').value;
 const shown=owing.filter(r=>f==='all'||(f==='overdue'&&paymentStatus(r)==='Overdue')||(f==='unpaid'&&recReceived(r)<=0.005)||(f==='partial'&&recReceived(r)>0.005));
 $('alertList').innerHTML=shown.map(r=>`<div class="entry"><strong>${escapeHtml(r.customer)} · ${escapeHtml(r.reg)}</strong><small>${escapeHtml(paymentStatus(r))} · Safari ${escapeHtml(r.start)} to ${escapeHtml(r.end)} · Due ${escapeHtml(r.paymentDueDate||'Not set')} · Expected ${money(recIncome(r))} · Received ${money(recReceived(r))} · <b>Outstanding ${money(Math.max(0,recIncome(r)-recReceived(r)))}</b></small><button type="button" data-alert-invoice="${escapeHtml(r.id)}">View Invoice</button></div>`).join('')||'<p class="hint">No customers match this filter.</p>';
}
function printDocument(title,body){
 const css='body{font-family:Arial,sans-serif;color:#143d35;padding:24px;line-height:1.55}h1{font-size:22px}h2{font-size:18px}table{width:100%;border-collapse:collapse;margin:18px 0}th,td{border:1px solid #b8c9c1;padding:9px;text-align:left}th{background:#e9f2ed}.toolbar{margin-bottom:18px}button{padding:10px 14px;background:#176c50;color:white;border:0;border-radius:5px}@media print{.toolbar{display:none}body{padding:0}}';
 const content=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)}</title><style>${css}</style></head><body><div class="toolbar"><button onclick="window.print()">Print / Save as PDF</button> <button onclick="history.back()">Back to app</button></div>${ALANANA_LOGO_HEADER}<h2>${escapeHtml(title)}</h2>${body}<p><small>Generated ${escapeHtml(today)} · Amounts in USD unless otherwise indicated. This document is generated from locally saved records.</small></p></body></html>`;
 const blob=new Blob([content],{type:'text/html'});const url=URL.createObjectURL(blob);
 // Reuse the same preview strategy as the existing reports: no pop-up dependency.
 const frame=$('alananaDocumentPreview');if(frame){delete frame.dataset.invoiceSafari;frame.src=url;$('alananaPreviewWrap').classList.remove('hidden');$('alananaPreviewWrap').scrollIntoView({behavior:'smooth'});}else{const a=document.createElement('a');a.href=url;a.download='Alanana_'+title.replace(/[^a-z0-9]+/gi,'_')+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
}
function invoiceFor(r){
 if(typeof window.alananaProfessionalInvoice==='function') return window.alananaProfessionalInvoice(r);
 notify('Professional invoice module not loaded. Refresh the app and try again.');
}
$('invoiceBtn').addEventListener('click',()=>{const r=db.safaris.find(x=>x.id===$('documentSafari').value);if(!r){notify('Select a safari booking first.');return}invoiceFor(r)});
$('receiptList').addEventListener('click',e=>{const b=e.target.closest('[data-print-receipt]');if(!b)return;const p=db.payments.find(x=>x.id===b.dataset.printReceipt);if(!p)return;const r=db.safaris.find(x=>x.id===p.safariId);if(!r)return;printDocument('Payment Receipt',`<h3>Receipt for: ${escapeHtml(r.customer)}</h3><p><strong>Customer name / Received from:</strong> ${escapeHtml(r.customer)}<br><strong>Vehicle:</strong> ${escapeHtml(r.reg)}<br><strong>Payment date:</strong> ${escapeHtml(p.date)}<br><strong>Payment type:</strong> ${escapeHtml(p.type)}<br><strong>Receipt reference:</strong> ${escapeHtml(p.id)}</p><table><tr><th>Payment</th><th>Amount</th></tr><tr><td>Original payment</td><td>${escapeHtml(p.currency)} ${Number(p.amount).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</td></tr><tr><td>USD equivalent</td><td>${money(payUSD(p))}</td></tr><tr><td>Saved exchange rate (TZS per USD)</td><td>${Number(p.fx)}</td></tr></table><p>This receipt confirms only the payment shown above, not necessarily full settlement of the booking.</p>`)});
$('alertList').addEventListener('click',e=>{const b=e.target.closest('[data-alert-invoice]');if(!b)return;const r=db.safaris.find(x=>x.id===b.dataset.alertInvoice);if(r)invoiceFor(r)});

