// Dashboard shortcuts and inclusive safari booking calendar. Read-only; never alters saved records.
document.querySelectorAll('[data-dash-open]').forEach(btn=>btn.addEventListener('click',()=>{
 const target=btn.dataset.dashOpen;
 if(target==='calendar'){$('dashCalendarSection').scrollIntoView({behavior:'smooth',block:'start'});return;}
 show(target);
}));
// Navigate booking calendar independently from financial dashboard month.
function shiftCalendarMonth(delta){
 const input=$('calendarMonth');
 const value=/^\d{4}-\d{2}$/.test(input.value)?input.value:$('dashboardMonth').value;
 const [year,month]=value.split('-').map(Number);
 const target=new Date(Date.UTC(year,month-1+delta,1));
 input.value=target.getUTCFullYear()+'-'+String(target.getUTCMonth()+1).padStart(2,'0');
 renderDashboardCalendar(input.value);
}
$('calendarPrevMonth').addEventListener('click',()=>shiftCalendarMonth(-1));
$('calendarNextMonth').addEventListener('click',()=>shiftCalendarMonth(1));
$('calendarMonth').addEventListener('change',()=>renderDashboardCalendar($('calendarMonth').value));
$('calendarToday').addEventListener('click',()=>{
 const now=new Date();$('calendarMonth').value=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');
 renderDashboardCalendar($('calendarMonth').value);
});
function renderDashboardCalendar(month){
 const holder=$('dashCalendar'),detail=$('dashCalendarDetail');
 if(!/^\d{4}-\d{2}$/.test(month)){holder.textContent='Choose a valid month.';detail.textContent='';return;}
 const [year,mo]=month.split('-').map(Number);
 const last=new Date(Date.UTC(year,mo,0)).getUTCDate();
 const offset=(new Date(Date.UTC(year,mo-1,1)).getUTCDay()+6)%7;
 let html='<div class="dash-weekday">Mon</div><div class="dash-weekday">Tue</div><div class="dash-weekday">Wed</div><div class="dash-weekday">Thu</div><div class="dash-weekday">Fri</div><div class="dash-weekday">Sat</div><div class="dash-weekday">Sun</div>';
 for(let i=0;i<offset;i++)html+='<span class="dash-blank"></span>';
 for(let day=1;day<=last;day++){
  const date=month+'-'+String(day).padStart(2,'0');
  const active=db.safaris.filter(r=>r.status!=='cancelled'&&r.start&&r.end&&r.start<=date&&bookingEnd(r)>=date);
  const vehicleRegs=[...new Set(active.map(r=>String(r.reg||'').toUpperCase()))];
  const conflictRegs=vehicleRegs.filter(reg=>active.filter(r=>String(r.reg||'').toUpperCase()===reg).length>1);
  html+=`<button type="button" class="dash-day ${active.length?'dash-booked':''} ${conflictRegs.length?'dash-conflict':''}" data-calendar-date="${date}" aria-label="${date}: ${vehicleRegs.join(', ')||'No vehicles booked'}"><strong>${day}</strong>${active.length?`<small>${vehicleRegs.map(x=>escapeHtml(x)).join('<br>')}</small>`:''}${conflictRegs.length?'<small>⚠ Overlap</small>':''}</button>`;
 }
 holder.innerHTML=html;
 detail.innerHTML='<p class="hint">Select a date to see its safari bookings.</p>';
}
$('dashCalendar').addEventListener('click',e=>{
 const btn=e.target.closest('[data-calendar-date]');if(!btn)return;
 const date=btn.dataset.calendarDate;
 const booked=db.safaris.filter(r=>r.status!=='cancelled'&&r.start&&r.end&&r.start<=date&&bookingEnd(r)>=date);
 const duplicateRegs=[...new Set(booked.map(r=>r.reg))].filter(reg=>booked.filter(r=>r.reg===reg).length>1);
 $('dashCalendarDetail').innerHTML=`<h4>Bookings on ${escapeHtml(date)}</h4>`+(duplicateRegs.length?`<p class="hint" style="color:#a43a23;font-weight:bold">⚠ Vehicle booking overlap: ${duplicateRegs.map(escapeHtml).join(', ')}</p>`:'')+(booked.length?booked.map(r=>`<div class="entry"><strong>🚙 ${escapeHtml(r.reg)} — ${escapeHtml(r.customer)}</strong><small>${escapeHtml(r.start)} to ${escapeHtml(r.end)} · ${escapeHtml(safariStatus(r))}</small><button type="button" data-calendar-change-vehicle="${escapeHtml(r.id)}">Change vehicle / dates</button></div>`).join(''):'<p class="hint">No safaris booked for this date.</p>');
});

function openFinishSafari(r){
 const now=new Date(), localDate=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');
 const d=document.createElement('dialog');d.style.cssText='width:min(90vw,420px);border:1px solid #b8cbbf;border-radius:12px;padding:20px;color:#193f32;background:white';
 d.innerHTML=`<form><h3>Finish Safari</h3><p><strong>${escapeHtml(r.customer)} · ${escapeHtml(r.reg)}</strong></p><p>Start date: ${escapeHtml(r.start)}<br>Expected end date: ${escapeHtml(r.end)}</p><label>Actual finish date <input name="finishDate" type="date" required min="${escapeHtml(r.start)}" max="${localDate}" value="${localDate}"></label><p class="hint" data-duration></p><p class="hint" data-error role="alert"></p><button type="button" data-cancel>Cancel</button> <button type="submit">Finish Safari</button></form>`;
 document.body.appendChild(d);const f=d.querySelector('form'),input=f.elements.finishDate,err=d.querySelector('[data-error]');
 const duration=()=>{const n=(Date.parse(input.value)-Date.parse(r.start))/86400000+1;d.querySelector('[data-duration]').textContent=n>0?'Actual duration: '+n+' days · Paid hire days: '+r.days:'';};input.addEventListener('input',duration);duration();
 d.querySelector('[data-cancel]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());
 f.addEventListener('submit',e=>{e.preventDefault();const date=input.value;if(!date||date<r.start||date>localDate)return;const conflicts=overlappingVehicleBookings(r.reg,r.start,date,r.id);if(conflicts.length){err.textContent=overlapMessage(conflicts);return;}const oldStatus=r.status,oldDate=r.completedAt;r.status='completed';r.completedAt=date;if(!persist()){r.status=oldStatus;if(oldDate===undefined)delete r.completedAt;else r.completedAt=oldDate;err.textContent='Could not save. Please try again.';return;}d.close();notify('Safari marked Completed. All financial records are retained.');});d.showModal();
}
